use super::*;

// Generated by Cloud's real CanonicalManifest + VerifyArchive, not a Rust reimplementation.
#[tokio::test]
async fn cloud_generated_zip_installs_and_cold_loads_through_public_protocol() {
    let item: Value = serde_json::from_str(include_str!(
        "../../src/market/testdata/cloud-plugin-item.json"
    ))
    .unwrap();
    let bytes = include_bytes!("../../src/market/testdata/cloud-plugin.zip").to_vec();
    let temp = TempDir::new().unwrap();
    let f = Fixture::start().await;
    let item = package::configure_artifact(&f, item, bytes);
    let current = server(temp.path()).await;
    login(&f, &current).await;
    let listed = rpc(&current, "plugin/list", cloud()).await;
    assert_eq!(
        summary(&listed)["remoteRelease"],
        reference(&item["release"])
    );
    let mut params = install();
    params["remoteRelease"] = reference(&item["release"]);
    assert_eq!(
        rpc(&current, "plugin/install", params).await["authPolicy"],
        "ON_INSTALL"
    );
    let installed = rpc(&current, "plugin/installed", json!({})).await;
    assert_eq!(
        summary(&installed)["localRelease"],
        reference(&item["release"])
    );
    let skill = rpc(&current, "plugin/skill/read", json!({
        "remoteMarketplaceName":MARKET,"remotePluginId":"item_research","skillName":"research:research"
    })).await;
    assert!(skill["contents"]
        .as_str()
        .unwrap()
        .contains("Research instructions"));
    let cold = server(temp.path()).await;
    assert_eq!(
        summary(&rpc(&cold, "plugin/installed", json!({})).await),
        summary(&installed)
    );
    assert_eq!(f.count("/market/acquisitions"), 1);
    assert_eq!(f.count("/download-tickets"), 1);
    assert!(f
        .state
        .lock()
        .unwrap()
        .calls
        .iter()
        .any(|(path, _, bearer)| path == "/bundle" && bearer.is_empty()));
}
